<?php $this->assign('title', 'Caixas'); ?>
<div class="d-flex justify-content-between mb-4"><h1 class="h3">Caixas</h1><?= $this->Html->link('Abrir caixa', ['action' => 'abrir'], ['class' => 'btn btn-primary']) ?></div>
<div class="card border-0 shadow-sm"><table class="table table-hover mb-0"><thead><tr><th>Abertura</th><th>Operador</th><th>Status</th><th>Inicial</th><th>Final</th><th></th></tr></thead><tbody><?php foreach ($caixas as $caixa): ?><tr><td><?= h($caixa->aberto_em->format('d/m/Y H:i')) ?></td><td><?= h($caixa->usuario_abertura->nome ?? '-') ?></td><td><?= h($caixa->status) ?></td><td><?= h($caixa->saldo_inicial) ?></td><td><?= h($caixa->saldo_final ?? '-') ?></td><td><?php if ($caixa->status === 'aberto'): ?><?= $this->Html->link('Movimentar', ['action' => 'movimentar', $caixa->id], ['class' => 'btn btn-sm btn-outline-primary']) ?> <?= $this->Form->postLink('Fechar', ['action' => 'fechar', $caixa->id], ['class' => 'btn btn-sm btn-outline-danger', 'confirm' => 'Fechar caixa?']) ?><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
